insert into public.chapter_content(n,content) values (3,$j${"id": 3, "title": "شکل‌های هندسی و تقارن", "bg": 1, "lessons": [["یادآوری شکل‌های هندسی", "نام شکل‌ها و تعداد ضلع‌هایشان را به یاد بیاور.", [["shape", {}], ["shape", {}], ["shape", {"mode": "sides", "set": ["مثلث", "مربع", "مستطیل", "پنج‌ضلعی", "شش‌ضلعی"]}], ["shape", {"mode": "sides", "set": ["مثلث", "مربع", "پنج‌ضلعی", "شش‌ضلعی"]}]]], ["روابط بین شکل‌ها", "با کنار هم گذاشتن شکل‌ها، شکل‌های تازه می‌سازیم.", [["rel", {}], ["rel", {}], ["rel", {}], ["rel", {}]]], ["حل مسئله: الگویابی", "الگو را پیدا کن و ادامه بده.", [["pat", {"k": ["AB"]}], ["pat", {"k": ["AAB"]}], ["pat", {"k": ["ABC"]}], ["pat", {"k": ["ABB", "AABB"]}]]], ["مفهوم تقارن", "دو نیمهٔ شکل متقارن مثل آینه هستند.", [["sym", {}], ["sym", {}], ["sym", {}], ["fact", {"pool": [["یک مربع چند خط تقارن دارد?", "۴", ["۱", "۲", "۸"]], ["مستطیل (غیر مربع) چند خط تقارن دارد?", "۲", ["۱", "۴", "۶"]], ["مثلث منظم (متساوی‌الاضلاع) چند خط تقارن دارد?", "۳", ["۱", "۲", "۶"]], ["دایره چند خط تقارن دارد?", "بی‌شمار", ["۱", "۲", "۴"]]]}]]], ["مرور فصل سوم", "مرور شکل‌ها، الگو و تقارن.", [["shape", {}], ["pat", {}], ["sym", {}], ["shape", {"mode": "sides", "set": ["مثلث", "مربع", "پنج‌ضلعی", "شش‌ضلعی"]}]]]]}$j$::jsonb) on conflict (n) do update set content=excluded.content;
insert into public.chapter_content(n,content) values (4,$j${"id": 4, "title": "پول و عددهای سه‌رقمی", "bg": 2, "lessons": [["معرفی پول", "سکه‌ها و اسکناس‌ها را جمع کن.", [["money", {"k": 3}], ["money", {"k": 4}], ["money", {"k": 4}], ["money", {"k": 4, "max": 15000}]]], ["معرفی عددهای سه‌رقمی", "صدگان، دهگان و یکان.", [["pv3", {"lo": 100, "hi": 399}], ["pv3", {"lo": 200, "hi": 599}], ["pv3", {"lo": 300, "hi": 699}], ["pv3", {"lo": 100, "hi": 799}]]], ["حل مسئله: حذف حالت‌های نامطلوب", "گزینه‌های نادرست را حذف کن.", [["clue", {}], ["clue", {}], ["clue", {"d3": 1}], ["clue", {"d3": 1}]]], ["عددهای سه‌رقمی تقریبی", "عدد را به نزدیک‌ترین ده‌تایی یا صدتایی گرد کن.", [["round", {"to": 10, "lo": 3, "hi": 9}], ["round", {"to": 10, "lo": 10, "hi": 60}], ["round", {"to": 100, "lo": 1, "hi": 8}], ["round", {"to": 100, "lo": 1, "hi": 8}]]], ["آمادگی برای جمع و تفریق", "جمع و تفریق را آماده شو.", [["ab", {"lo": 11, "hi": 50, "op": "+", "c": false, "sum": 99}], ["ab", {"lo": 15, "hi": 70, "op": "+", "c": true, "sum": 99}], ["ab", {"lo": 21, "hi": 90, "op": "-", "c": false}], ["ab", {"lo": 21, "hi": 90, "op": "-", "c": true}]]], ["مرور فصل چهارم", "مرور پول و عددهای سه‌رقمی.", [["money", {"k": 4}], ["pv3", {"lo": 100, "hi": 899}], ["round", {"to": 10, "lo": 10, "hi": 80}], ["clue", {"d3": 1}]]]]}$j$::jsonb) on conflict (n) do update set content=excluded.content;
insert into public.chapter_content(n,content) values (5,$j${"id": 5, "title": "اندازه‌گیری طول", "bg": 1, "lessons": [["اندازه‌گیری طول", "طول را با خط‌کش اندازه می‌گیریم.", [["ruler", {}], ["ruler", {}], ["fact", {"pool": [["طول مداد را با چه واحدی اندازه می‌گیریم?", "سانتی‌متر", ["کیلوگرم", "لیتر", "ثانیه"]], ["کدام وسیله طول را اندازه می‌گیرد?", "خط‌کش", ["ترازو", "ساعت", "پیمانه"]]]}], ["ruler", {}]]], ["اندازه‌گیری دقیق‌تر", "با واحدهای کوچک‌تر دقیق‌تر اندازه می‌گیریم.", [["ruler", {"u": "mm"}], ["ruler", {"u": "mm"}], ["ruler", {}], ["ruler", {"u": "mm"}]]], ["حل مسئله: حدس و آزمایش", "حدس بزن، امتحان کن و درستش کن.", [["gt", {}], ["gt", {}], ["gt", {}], ["gt", {}]]], ["واحد سانتی‌متر", "سانتی‌متر یکی از واحدهای اندازه‌گیری است.", [["ruler", {}], ["ruler", {}], ["ruler", {}], ["ruler", {}]]], ["واحد میلی‌متر", "میلی‌متر واحد کوچک‌تر است.", [["ruler", {"u": "mm"}], ["ruler", {"u": "mm"}], ["fact", {"pool": [["۱۰ میلی‌متر برابر است با?", "۱ سانتی‌متر", ["۱ متر", "۱۰ سانتی‌متر", "۱۰۰ سانتی‌متر"]], ["برای اندازه‌گیری ضخامت یک کتاب کدام واحد مناسب‌تر است?", "میلی‌متر", ["متر", "کیلومتر", "لیتر"]]]}], ["ruler", {"u": "mm"}]]], ["مرور فصل پنجم", "مرور اندازه‌گیری.", [["ruler", {}], ["ruler", {"u": "mm"}], ["gt", {}], ["ruler", {"u": "mm"}]]]]}$j$::jsonb) on conflict (n) do update set content=excluded.content;
