insert into public.chapter_content(n,content) values (7,$j${"id": 7, "title": "کسر و احتمال", "bg": 1, "lessons": [["قسمتی از یک واحد", "یک چیز را به قسمت‌های مساوی تقسیم می‌کنیم.", [["frac", {"d": [2, 3, 4]}], ["frac", {"d": [2, 3, 4]}], ["fcolor", {"d": [2, 3, 4]}], ["fcolor", {"d": [2, 3, 4]}]]], ["نمایش کسرها", "کسر را با شکل نشان می‌دهیم.", [["frac", {"d": [3, 4, 5, 6, 8]}], ["frac", {"d": [3, 4, 5, 6, 8]}], ["fcolor", {"d": [4, 5, 6, 8]}], ["fcolor", {"d": [4, 5, 6, 8]}]]], ["حل مسئله: مسئله ساده‌تر", "مسئله را ساده‌تر کن.", [["two", {"lo": 8, "hi": 16}], ["two", {"lo": 8, "hi": 18}], ["two", {"lo": 10, "hi": 20}], ["story", {"lo": 8, "hi": 18}]]], ["مفهوم احتمال", "قطعی، ممکن، غیرممکن.", [["prob", {"mode": "cert"}], ["prob", {"mode": "cert"}], ["prob", {"mode": "most"}], ["prob", {"mode": "most"}]]], ["احتمال و کسر", "احتمال را با کسر نشان می‌دهیم.", [["prob", {"mode": "frac"}], ["prob", {"mode": "frac"}], ["prob", {"mode": "frac"}], ["prob", {"mode": "frac"}]]], ["مرور فصل هفتم", "مرور کسر و احتمال.", [["frac", {"d": [2, 3, 4, 5, 6]}], ["fcolor", {"d": [3, 4, 6]}], ["prob", {"mode": "cert"}], ["prob", {"mode": "frac"}]]]]}$j$::jsonb) on conflict (n) do update set content=excluded.content;
